def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]
    wcols=[j for j in range(W) if len({g[i][j] for i in range(H)})==1 and g[0][j]!=bg]
    ws=set(wcols); wc=g[0][min(ws)]
    MR=[i for i,row_ in enumerate(g) if any(v!=bg and v!=wc for v in row_)]
    def near_of(m): return min(ws,key=lambda w:abs(m-w))
    for i in MR:
        row_=g[i]
        ms=[j for j,v in enumerate(row_) if v!=bg and v!=wc]
        m=min(ms); mc=row_[m]
        nr=near_of(m)
        for j in (nr-1,nr+1):
            if 0<=j<W: out[i][j]=wc
        out[i][nr]=mc
        lo,hi=(m,nr-2) if m<nr else (nr+2,m)
        for j in range(lo,hi+1):
            out[i][j]=mc
    for i in MR:
        row_=g[i]
        ms=[j for j,v in enumerate(row_) if v!=bg and v!=wc]
        m=min(ms); nr=near_of(m)
        for di in (-1,1):
            r2=i+di
            if 0<=r2<H:
                for j in (nr-1,nr+1):
                    if 0<=j<W: out[r2][j]=wc
    return out
